function breedEntries(species){return (breedOptionsRequired[species]||[]).map(([value,name],i)=>{const source=(breedCatalogData[species==='cat'?'cats':'dogs']||[]).find(x=>x.name===name);const fallback=`${species==='cat'?'cat':'dog'}-${String(i+1).padStart(2,'0')}`;const id=breedAssetByName[name]||source?.id||fallback;return {value,name,id,image:`assets/breeds/${id}.png`}})}
